export const readableName=value=>String(value).replace(/^(?:MUS_|WEATHER_|MAP_TYPE_|MAPSEC_|MAP_BATTLE_SCENE_)/,'').replace(/_/g,' ').replace(/([a-z0-9])([A-Z])/g,'$1 $2').toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());
export function createBeginnerFlow({S,$,openDrafts}){
 const menu=document.querySelector('.more-map-tools'),entries=menu.querySelector('div'),dialog=document.createElement('dialog');dialog.id='taskDialog';dialog.className='task-dialog';dialog.setAttribute('aria-labelledby','taskTitle');dialog.innerHTML=`<div class="dialog-head"><h2 id="taskTitle">What would you like to do?</h2><button id="closeTasks" aria-label="Close task choices">×</button></div><p class="studio-note">Choose a goal. TileForge will open the right tool and show your next step.</p><label class="task-search-label">Find a task<input id="taskSearch" type="search" placeholder="Try paint, doorway, weather or save…" autocomplete="off"></label><h3 class="task-section-title">Everyday tasks</h3><div class="task-grid" id="commonTasks"></div><p id="taskEmpty" class="studio-note" hidden>No matching task. Try a shorter word, or clear the search.</p><details id="advancedTasks"><summary>More map tools</summary><div class="task-grid" id="extraTasks"></div></details><div class="task-footer"><button id="taskDrafts">Manage saved drafts</button><button id="taskGuide">Read quick guide</button></div>`;document.body.append(dialog);
 const descriptions={properties:['Change map settings','Set music, weather and running rules.'],connections:['Connect map edges','Let the player walk between neighboring maps.'],replace:['Replace a tile everywhere','Swap artwork while keeping movement settings.'],shift:['Move the whole terrain','Shift terrain; events stay in place.']};
 for(const b of [...entries.children]){const copy=descriptions[b.dataset.manage];b.textContent=copy[0];const small=document.createElement('small');small.textContent=copy[1];b.append(small);$('extraTasks').append(b);}
 menu.querySelector('summary').textContent='Tools & tasks';menu.querySelector('summary').addEventListener('click',e=>{e.preventDefault();menu.open=false;dialog.showModal();});
 dialog.addEventListener('click',e=>{if(e.target.closest('[data-manage]'))dialog.close();},true);
 let action=()=>{},ownMessage='',guided=null,step=0;const next=document.createElement('button');next.id='nextStepButton';next.type='button';next.className='next-step-button';$('nextAction').after(next);$('nextAction').setAttribute('aria-live','polite');next.onclick=()=>action();
 function hint(text,label,fn){ownMessage=text;$('nextAction').textContent=text;next.textContent=label;action=fn;}
 function tiles(){const narrow=matchMedia('(max-width:1100px)').matches;if(narrow){if(!$('paletteDialog').open)$('brushToggle').click();}else document.querySelector('.inspector').scrollTo({top:0,behavior:'smooth'});}
 function review(){if(!$('eventsPanel').open)$('eventsPanel').open=true;$('reviewEventsBtn').click();}
 const clickTool=t=>document.querySelector('.toolbar [data-tool="'+t+'"]').click();
 const tasks=[['paint','Paint the map','Choose artwork, then tap or drag to paint.'],['movement','Change where the player can walk','Allow or block passage without changing artwork.'],['events','Add a person, sign or doorway','Open NPCs & events, then choose what to place.'],['room','Create a room or outdoor area','Pick a size and a matching artwork template.'],['warp','Link a doorway','Choose where an entrance leads and its return point.'],['save','Save or share my work','Save a device draft or export a portable file.']];
 for(const[id,title,description]of tasks){const b=document.createElement('button');b.type='button';b.dataset.task=id;const strong=document.createElement('strong');strong.textContent=title;const small=document.createElement('small');small.textContent=description;b.append(strong,small);$('commonTasks').append(b);b.onclick=()=>{dialog.close();if(!['paint','movement','events'].includes(id)&&guided)$('guidedHide').click();if(id==='paint'){clickTool('pan');tiles();$('metatileMode').click();hint('Step 1: choose a tile. Close the brush drawer if it stays open, then paint on the map.','Show tiles',tiles);}if(id==='movement'){tiles();$('movementMode').click();hint('Choose Walkable or Blocked and an elevation. Keep existing preserves height. Then paint on the map.','Choose Paint',()=>clickTool('pencil'));}if(id==='events'){$('eventsPanel').open=true;hint('Choose + Add NPC to browse every project sprite, or choose Sign, Trigger or Warp. Then tap its map position.','Explain events',()=>$('eventsPanel').querySelector('[data-tip]').click());}if(id==='room')$('newCellBtn').click();if(id==='warp')$('linkWarpBtn').click();if(id==='save')showSave();if(['paint','movement','events'].includes(id))startGuide(id);};}

 const search=$('taskSearch');let advancedOpen=false;
 function filterTasks(){const q=search.value.trim().toLowerCase(),buttons=[...dialog.querySelectorAll('.task-grid>button')];let count=0;for(const b of buttons){b.hidden=!!q&&!b.textContent.toLowerCase().includes(q);if(!b.hidden)count++;}$('taskEmpty').hidden=count>0;$('advancedTasks').hidden=!!q&&![...$('extraTasks').children].some(b=>!b.hidden);if(q){if(!search.dataset.filtering){advancedOpen=$('advancedTasks').open;search.dataset.filtering='1';}$('advancedTasks').open=true;}else if(search.dataset.filtering){delete search.dataset.filtering;$('advancedTasks').open=advancedOpen;}}
 search.addEventListener('input',filterTasks);dialog.addEventListener('close',()=>{search.value='';filterTasks();});
 const guide=document.createElement('section');guide.id='guidedTask';guide.className='guided-task';guide.hidden=true;guide.setAttribute('aria-label','Guided task');guide.innerHTML='<div class="guided-heading"><strong id="guidedTitle"></strong><button id="guidedHide" type="button" aria-label="Hide task guide">×</button></div><ol id="guidedSteps"></ol><p id="guidedInstruction" aria-live="polite"></p><div class="guided-actions"><button id="guidedBack" type="button">Back</button><button id="guidedNext" type="button" class="primary"></button><button id="guidedChange" type="button">Change task</button></div>';
 document.querySelector('.world-actions').after(guide);
 const brushReady=document.createElement('button');brushReady.id='guidedBrushReady';brushReady.type='button';brushReady.className='primary guided-brush-ready';brushReady.hidden=true;$('paletteDialog').querySelector('.dialog-head').after(brushReady);brushReady.onclick=()=>$('guidedNext').click();
 const plans={
  paint:{title:'Paint the map',steps:['Choose artwork','Paint on the map','Check & save'],text:['Choose a tile in the brush panel. Your map stays unchanged until you paint.','Tap or drag on the map. Undo reverses your last stroke. You can still change brushes.','Use Original to compare your work, then save a draft or export a file.'],actions:['Use brush & paint','Check & save','Save options']},
  movement:{title:'Change where the player can walk',steps:['Choose passage & level','Paint movement','Check & save'],text:['Choose Walkable or Blocked. Keep existing preserves height; a numbered choice sets it too. Use ? for explanations.','Tap or drag on the map. Artwork stays the same; only the enabled movement fields change. Undo reverses a stroke.','Review the movement overlay, then save. Rebuild and test in game to check stairs, water and bridges.'],actions:['Use brush & paint','Check & save','Save options']},
  events:{title:'Add a person, sign or doorway',steps:['Choose an event','Place & configure','Check & save'],text:['Choose a person, sign, trigger or warp in NPCs & events. A sprite choice only prepares placement.','Choose the event’s map position, then fill in its details and use its explicit Save or Apply action.','Review events for advisory checks, inspect your change and save your work.'],actions:['Go to map','Review events','Save options']}
 };
 function closePalette(){if($('paletteDialog').open)$('paletteDialog').querySelector('[data-close]').click();}
 function startGuide(id){guided=id;step=0;guide.hidden=false;drawGuide();}
 function drawGuide(){const p=plans[guided];brushReady.hidden=step!==0;brushReady.textContent=p.actions[0];$('guidedTitle').textContent=p.title;const ol=$('guidedSteps');ol.replaceChildren();p.steps.forEach((label,i)=>{const li=document.createElement('li');li.textContent=(i+1)+' · '+label;if(i===step)li.setAttribute('aria-current','step');ol.append(li);});$('guidedInstruction').textContent=p.text[step];$('guidedNext').textContent=p.actions[step];$('guidedBack').disabled=step===0;document.querySelector('.world-actions').classList.add('guidance-active');}
 $('guidedHide').onclick=()=>{guide.hidden=true;guided=null;brushReady.hidden=true;document.querySelector('.world-actions').classList.remove('guidance-active');};
 $('guidedChange').onclick=()=>dialog.showModal();
 $('guidedBack').onclick=()=>{if(step>0)step--;drawGuide();if(step===0){if(guided==='events')$('eventsMode').click();else tiles();}};
 $('guidedNext').onclick=()=>{if(!guided)return;if(step===2){showSave();return;}closePalette();if(step===0){clickTool(guided==='events'?'pan':'pencil');step=1;}else{step=2;if(guided==='events')review();}drawGuide();};
 const save=document.createElement('dialog');save.id='saveChoices';save.className='task-dialog save-choices';save.setAttribute('aria-labelledby','saveChoicesTitle');save.innerHTML='<div class="dialog-head"><h2 id="saveChoicesTitle">How would you like to save?</h2><button type="button" data-close aria-label="Close save choices">×</button></div><p class="studio-note">Choose where your work should go. Exporting does not update the game repository.</p><div class="save-choice-list"><button id="guidedSaveDraft" type="button"><strong>Save on this device</strong><small>A local draft. Continue here later; it is not a shared backup.</small></button><button id="guidedSaveProject" type="button"><strong>Download an editable project</strong><small>A portable backup to reopen in TileForge or send to someone.</small></button><button id="guidedSaveChanges" type="button"><strong>Export game changes</strong><small>Review and download changed source files for integration and a separate game build.</small></button></div>';
 new MutationObserver(()=>{if(document.body.dataset.stage==='load'&&guided)$('guidedHide').click();}).observe(document.body,{attributes:true,attributeFilter:['data-stage']});
 document.body.append(save);save.querySelector('[data-close]').onclick=()=>save.close();
 function showSave(){if(!save.open)save.showModal();const source=!S.rom;$('guidedSaveChanges').querySelector('strong').textContent=source?'Export game changes':'Export edited ROM';$('guidedSaveChanges').querySelector('small').textContent=source?'Review and download changed source files for integration and a separate game build.':'Review export options and save a new copy of the edited ROM.';}
 $('guidedSaveDraft').onclick=()=>{save.close();$('saveDraftBtn').click();};$('guidedSaveProject').onclick=()=>{save.close();$('projectSaveBtn').click();};$('guidedSaveChanges').onclick=()=>{save.close();$('exportBtn').click();};
 $('manageDraftSlots').onclick=openDrafts;$('exportDraftBackup').onclick=()=>$('exportBtn').click();$('closeTasks').onclick=()=>dialog.close();$('taskDrafts').onclick=()=>{dialog.close();openDrafts();};$('taskGuide').onclick=()=>{dialog.close();$('helpBtn').click();};
 document.querySelectorAll('.toolbar [data-tool]').forEach(b=>b.addEventListener('click',()=>{const mode=b.dataset.tool;if(mode==='pan')hint('Move: drag to look around. Your map stays unchanged. Pinch to zoom; Fit brings the map back into view.','Choose a task',()=>dialog.showModal());if(mode==='pencil')hint(S.movement?'Paint movement: tap or drag. The selected passage/height fields change; artwork stays the same.':'Paint: tap or drag to place your selected tile. Undo reverses one stroke.','Choose a brush',tiles);if(mode==='fill')hint('Fill: tap once to replace a connected matching area. Undo reverses the fill. Check the selected fields first.','Explain Fill',()=>document.querySelector('.tools-help').click());if(mode==='pick')hint('Pick: tap a tile you want to reuse, then switch back to Paint.','Choose Paint',()=>clickTool('pencil'));}));
 // Existing tools can publish their own next-step text; keep its action relevant.
 new MutationObserver(()=>{const text=$('nextAction').textContent;if(text===ownMessage)return;ownMessage=text;if(/review|export|test/i.test(text)){next.textContent='Review events';action=review;}else{next.textContent='Choose a task';action=()=>dialog.showModal();}}).observe($('nextAction'),{childList:true,characterData:true,subtree:true});
 hint('Start here: choose a goal, or select Tiles and pick artwork for your map.','Choose a task',()=>dialog.showModal());
 return {brushChosen(){if(S.view==='map'&&!S.movement)hint('Your brush is ready. Choose Paint, then tap or drag across the map. Undo is always available.','Choose Paint',()=>clickTool('pencil'));}};
}
